arguments.command:
curl -sS https://slack.com/api/conversations.list -H 'Authorization: Bearer <TOKEN>' --data 'types=public_channel,private_channel&limit=1000' | python3 -c "
import json,sys
d=json.load(sys.stdin)
for k in ('channels','groups'):
    for c in d.get(k,[]):
        if 'eng' in c.get('name',''):
            print(k, c['id'], c['name'], c.get('is_private'))
"

